<?php
namespace App\Http\Controllers;
use App\Models\{Kecakapan,PenilaianKinerja,User}; use Illuminate\Http\Request;
class KinerjaController extends Controller { public function index(Request $r){$bulan=$r->integer('periode_bulan')?:now()->month;$tahun=$r->integer('periode_tahun')?:now()->year;$pegawai=$r->user()->isAdmin()?$r->integer('user_id'): $r->user()->id;$q=PenilaianKinerja::with(['user','kecakapan','penilai'])->where('periode_bulan',$bulan)->where('periode_tahun',$tahun);if($pegawai)$q->where('user_id',$pegawai);return view('kinerja.index',['nilai'=>$q->get(),'kecakapans'=>Kecakapan::all(),'users'=>User::where('role','pegawai')->get(),'bulan'=>$bulan,'tahun'=>$tahun]);}
 public function store(Request $r){$v=$r->validate(['kecakapan_id'=>'required|exists:kecakapan,id','nilai'=>'required|numeric|min:0|max:100','periode_bulan'=>'required|between:1,12','periode_tahun'=>'required|integer','user_id'=>'nullable|exists:users,id']);$v['user_id']=$r->user()->isAdmin() ? $r->integer('user_id') : $r->user()->id;abort_if(!$v['user_id'],422,'Pegawai wajib dipilih.');PenilaianKinerja::updateOrCreate(['user_id'=>$v['user_id'],'kecakapan_id'=>$v['kecakapan_id'],'periode_bulan'=>$v['periode_bulan'],'periode_tahun'=>$v['periode_tahun']],$v+['dinilai_oleh'=>$r->user()->id]);return back()->with('success',$r->user()->isAdmin()?'Penilaian kinerja disimpan.':'Progres kinerja berhasil disimpan.');} }
